<?php get_header(); ?><div class="container content-layout"><div class="primary-content"><header class="archive-header"><p class="eyebrow"><?php esc_html_e( 'Search', 'souqify' ); ?></p><h1><?php printf( esc_html__( 'Results for “%s”', 'souqify' ), esc_html( get_search_query() ) ); ?></h1></header><?php if ( have_posts() ) : ?><div class="posts-grid"><?php while ( have_posts() ) : the_post(); ?><article <?php post_class( 'post-card' ); ?>><a href="<?php the_permalink(); ?>"><?php if ( has_post_thumbnail() ) { the_post_thumbnail( 'medium_large' ); } ?></a><div class="post-card-body"><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php the_excerpt(); ?></div></article><?php endwhile; ?></div><?php souqify_pagination(); else : ?><div class="empty-state"><h2><?php esc_html_e( 'No results found', 'souqify' ); ?></h2><?php get_search_form(); ?></div><?php endif; ?></div><?php get_sidebar(); ?></div><?php get_footer(); ?>
